import{_ as t,C as i,o as r,c as n,E as s,a2 as a}from"./chunks/framework.BXyf8PVu.js";const f=JSON.parse('{"title":"Musico","description":"","frontmatter":{"pageClass":"project-case-study","title":"Musico","order":5},"headers":[],"relativePath":"projects/musico.md","filePath":"projects/musico.md"}'),d={name:"projects/musico.md"};function c(l,e,g,p,u,m){const o=i("ProjectHero");return r(),n("div",null,[s(o,{index:"05",eyebrow:"Software engineering · Native audio",title:"Musico: Native Offline Music Player",summary:"An offline, folder-first, multi-queue local music player built natively for Apple, Android, and Windows—with zero web wrappers and a shared cross-platform JavaScript extension runtime.",year:"2025–2026",role:"Architecture, native UI & audio engineering",methods:"SwiftUI · Jetpack Compose · .NET 8 WPF · JavaScriptCore / QuickJS / Jint",chart:"/charts/musico-architecture.html","image-alt":"Interactive architecture diagram of Musico across Apple, Android, and Windows native clients",docs:"https://musico.seanpnex.win",repo:"https://github.com/SEANPNEX/Musico"}),e[0]||(e[0]=a('<h2 id="the-question" tabindex="-1">The question <a class="header-anchor" href="#the-question" aria-label="Permalink to &quot;The question&quot;">​</a></h2><p>Most cross-platform desktop and mobile apps converge on Electron or embedded WebViews, trading memory footprint, native audio pipelines, and OS integration for a single UI layer. Meanwhile, listeners with large local music archives often care about two things streaming apps ignore: keeping their folder tree intact and juggling independent playback queues without losing their place.</p><p><strong>Musico</strong> explores the opposite trade-off: building a cozy, folder-first offline music player (inspired by <strong>Musicolet</strong> and <strong>YRRLYB/Aria</strong>) <strong>100% natively</strong> for Apple, Android, and Windows, while keeping the library model, playback semantics, and custom source extensions unified across platforms.</p><h2 id="three-native-clients-zero-web-wrappers" tabindex="-1">Three native clients, zero web wrappers <a class="header-anchor" href="#three-native-clients-zero-web-wrappers" aria-label="Permalink to &quot;Three native clients, zero web wrappers&quot;">​</a></h2><p>Each platform client uses its ecosystem&#39;s native UI toolkit, audio engine, and system media integration, paired with an embedded lightweight JavaScript engine for extensions:</p><table tabindex="0"><thead><tr><th>Client</th><th>Target Platforms</th><th>Tech Stack</th><th>Native Design &amp; Integration</th></tr></thead><tbody><tr><td><code>Musico/</code></td><td>iOS 17+, iPadOS, macOS (Catalyst)</td><td>Swift, SwiftUI (<code>@Observable</code>), <code>AVAudioEngine</code> + <code>AVAudioUnitEQ</code>, <code>MPNowPlayingInfoCenter</code>, <code>JavaScriptCore</code> (<code>Compression</code> + <code>CryptoKit</code>)</td><td>Apple HIG — tabs, sheets, and iOS swipe actions (<code>allowsFullSwipe: false</code> to prevent accidental folder deletion, plus Queue/Playlist swipe-to-remove <strong>Undo</strong>); <code>NSVisualEffectView</code> frosted translucency, independent sidebar color, <code>Cmd+K</code> Command Palette, Floating Mini-Player, and drag-and-drop on macOS</td></tr><tr><td><code>MusicoAndroid/</code></td><td>Android 8.0+ (API 26+)</td><td>Kotlin, Jetpack Compose, AndroidX Media3 (ExoPlayer + <code>MediaSessionService</code>), SAF <code>DocumentFile</code>, <code>DynamicsProcessing</code> EQ, <code>QuickJS</code> (<code>quickjs-kt</code>)</td><td>Material 3 / Material You — Dynamic Color, adaptive <code>NavigationBar</code> / <code>NavigationRail</code>, <code>ModalBottomSheet</code>, Outlook × Material You 2-stage <code>MusicoSwipeActionRow</code> swipe gestures (clean clipped back rail, haptic detent, <code>DragReorder</code> handle swipe-lock so <code>≡</code> handles never stick), single-line segmented pickers without selection checkmark crowding, dark-themed <code>MusicoSnackbarHost</code> snackbars with queue <strong>Undo</strong>, custom appearance themes, and device/<code>Musico</code>-folder delete</td></tr><tr><td><code>MusicoWindows/</code></td><td>Windows 10 (2004+) &amp; Windows 11</td><td>C# / .NET 8 WPF, NAudio (<code>BiQuadFilter</code> 10-band EQ), TagLibSharp, Windows 10 SMTC, <code>Jint</code></td><td>Fluent Design — Windows 11 DWM rounded corners/backdrop &amp; Acrylic, independent sidebar color &amp; opacity, <code>Ctrl+K</code> Command Palette, Floating Mini-Player, and drag-and-drop</td></tr></tbody></table><h2 id="core-capabilities" tabindex="-1">Core capabilities <a class="header-anchor" href="#core-capabilities" aria-label="Permalink to &quot;Core capabilities&quot;">​</a></h2><ul><li><strong>Folder-first library, drag-and-drop &amp; safe deletion:</strong> Mount local directories (<code>Music</code>, <code>Documents</code>, or custom folders) while preserving the underlying directory hierarchy, or drop local folders and audio files directly onto the macOS/Windows window (mounting dropped folders in <strong>Folders</strong> and playing dropped tracks immediately while copying outside-library files into the default music folder). When a drive is unplugged or a folder moves, <strong>Relocate</strong> reconnects tracks without losing playlists or listening history. Deletion cleanly separates <strong>Remove from Library</strong> from disk deletion (<strong>Move to Trash</strong> on macOS, <strong>Move to Recycle Bin</strong> on Windows, <strong>Delete from Device</strong> on iOS/Android including Android&#39;s <code>Musico</code> folder). Broad lossless and lossy playback spans FLAC, ALAC, WAV, AIFF, MP3, AAC/M4A (plus OGG, Opus, WMA, and WebM depending on platform).</li><li><strong>Cloud folders, optional Drive OAuth 2.0 &amp; offline sync:</strong> Mount public or cookie-authenticated sources directly inside <strong>Folders</strong>—covering <strong>YouTube / YouTube Music</strong> (playlists, <code>RD</code> mixes, albums, single tracks), <strong>Bilibili</strong> (<code>BV</code>/<code>av</code> multi-part videos, <code>favlist</code>, collections), and <strong>Google Drive</strong> (recursive folder discovery and single files). Public/shared Drive links remain zero-login, while optional <strong>Settings → Google Drive Account</strong> accepts a user&#39;s own free Desktop app OAuth 2.0 Client ID (<code>drive.readonly</code> + <code>userinfo.email</code>, Testing mode, automatic <code>http://127.0.0.1:&lt;port&gt;/oauth2callback</code>, 7-day Testing token with <strong>Reconnect Google Drive</strong>) for private folders and large-file download bypass. Tracks can be saved locally with a <code>.musico-cloud.json</code> manifest and refreshed incrementally via <strong>Update from Cloud</strong>.</li><li><strong>Multiple independent queues, deduplicated <code>Play Next</code> &amp; mobile swipe gestures:</strong> Spin up parallel queues for different moods or listening sessions; rename, reorder, clear, or switch queues anytime, with each queue persisting its own track, playback position, shuffle order, and repeat mode (<code>Off</code> / <code>All</code> / <code>One</code>). <strong>Deduplicated <code>Play Next</code></strong> across Apple, Android, and Windows (<code>insertNext</code>) moves existing non-current occurrences cleanly in the queue instead of duplicating tracks, leaving the playing song undisturbed. Aligned mobile swipe gestures bring <strong>Play Next</strong> on swipe-right; swipe-left on <strong>Library Songs</strong> opens a <strong>Remove from Library</strong> / <strong>Delete from Device</strong> confirmation dialog (disabled on ephemeral cloud previews); swipe-left on <strong>Queues</strong>, <strong>Playlists</strong>, and <strong>Favourites</strong> removes items immediately with <strong>Undo</strong> restoring the exact queue position, active track index, and playback resume timestamp; and Android raises the Folder swipe-delete threshold (<code>~44%</code> / <code>min 140dp</code>) to guard against accidental deletion.</li><li><strong>Unified Appearance &amp; desktop power features:</strong> Unified <strong>Settings</strong> (<code>Cmd+,</code> / <code>Ctrl+,</code>) offers System/Light/Dark modes, curated background &amp; accent presets, custom hex/RGB/system color pickers, a live <strong>Now Playing Preview</strong>, built-in <strong>WCAG 2.1 contrast check</strong> with one-click <strong>Auto-fix Contrast</strong>, and custom background images with <strong>Image Visibility</strong> (opacity) and <strong>Background Blur</strong>. Desktop adds a global <strong>Command Palette / Quick Jump</strong> (<code>Cmd+K</code> / <code>Ctrl+K</code>), <strong>Floating Mini-Player</strong> window (<code>Cmd+Shift+N</code> / <code>Ctrl+Shift+N</code>), and expanded keyboard shortcuts (Lyrics <code>Cmd+Shift+L</code> / <code>Ctrl+Shift+L</code> / <code>L</code>, Queue <code>Cmd+Shift+Q</code> / <code>Ctrl+Shift+Q</code> / <code>Q</code>, Seek <code>±10s</code>, Volume <code>±5%</code>, Mute, Shuffle/Repeat, Now Playing).</li><li><strong>Playback &amp; library craft:</strong><ul><li><strong>10-band ISO equalizer</strong> (<code>31 Hz</code>–<code>16 kHz</code>) with <code>-12 dB</code> to <code>+12 dB</code> preamp and 8 presets plus <code>Custom</code>.</li><li><strong>Synced &amp; plain lyrics</strong> with automatic fallback (<strong>Imported</strong> → <strong>Sidecar</strong> <code>.lrc</code>/<code>.txt</code> → <strong>Embedded</strong> tags), multi-timestamp <code>.lrc</code> parsing, UTF-8 / UTF-16 BOM / GB18030 decoding, tap-to-seek, customizable font size and alignment, and <strong>Sync to current line</strong>.</li><li><strong>Sleep timer, stats &amp; tag editor:</strong> <code>5</code>–<code>90</code> minute timers or end-of-track stop, listening stats (<strong>Recent</strong>, <strong>Plays</strong>, <strong>Not Lately</strong>, <strong>Never</strong>, plus <strong>Top Artists</strong> and <strong>Top Albums</strong>), inline metadata/cover-art editing, OS media controls, and live <code>English</code> / <code>简体中文</code> switching.</li></ul></li></ul><h2 id="cross-platform-javascript-extensions" tabindex="-1">Cross-platform JavaScript extensions <a class="header-anchor" href="#cross-platform-javascript-extensions" aria-label="Permalink to &quot;Cross-platform JavaScript extensions&quot;">​</a></h2><p>Rather than embedding a heavy WebView to support community or personal music sources, Musico executes a single CommonJS script (<code>.musico.js</code>) or ZIP bundle (<code>.musicoext</code>) directly inside each platform&#39;s native JS runtime (<strong>JavaScriptCore</strong> on Apple, <strong>QuickJS</strong> on Android, <strong>Jint</strong> on Windows):</p><ul><li><strong>Explicit permission review &amp; isolated sign-in:</strong> Newly imported extensions stay disabled until the user inspects declared <code>permissions.hosts</code> domain allowlists and capabilities (such as <code>&quot;cookie&quot;</code>, <code>&quot;qr_login&quot;</code>, <code>&quot;web_login&quot;</code>, <code>&quot;tree&quot;</code>, or <code>&quot;proxy&quot;</code>). The <code>&quot;web_login&quot;</code> capability paired with conditional manifest <code>webLogin</code> (<code>{ loginUrl, cookieDomains, requiredCookies?, userAgent? }</code>) opens an isolated, ephemeral OS WebView (<strong>WKWebView</strong> / <strong>Android WebView</strong> / <strong>WebView2</strong>) strictly for sign-in cookie capture—keeping the player UI 100% native—alongside masked <code>cookies.txt</code> file import.</li><li><strong>Official plugin ecosystem (<code>v2026.11.26</code>):</strong> Official plugins ship as ready-to-import bundles covering <strong>YouTube Search</strong> <code>v1.2.0</code> (<code>web_login</code> + quality tiers), <strong>Bilibili Search</strong> <code>v1.2.0</code> (<code>qr_login</code> + Hi-Res/FLAC tier), <strong>NetEase Cloud Music</strong> <code>v1.2.0</code> (9 quality tiers + <code>qr_login</code>), and <strong>Apple Music</strong> <code>v1.0.1</code> (Bearer token forwarding on <code>searchLyrics</code> + codecs/artwork fallback).</li><li><strong>Safe operations &amp; debugging:</strong> Includes per-extension settings panels, a 200-entry rolling log viewer, non-destructive disable/uninstall that preserves existing library tracks and cached audio, and a Node.js conformance runner (<code>docs/extensions/tools/mock-runner.mjs</code>) for verifying extension scripts locally.</li></ul><h2 id="distribution-release-engineering" tabindex="-1">Distribution &amp; release engineering <a class="header-anchor" href="#distribution-release-engineering" aria-label="Permalink to &quot;Distribution &amp; release engineering&quot;">​</a></h2><p>Multi-platform GitHub Actions workflows build, test, and publish tagged releases (latest <code>v1.3.4</code>) for all targets—producing a macOS Catalyst <code>.dmg</code>, iOS unsigned <code>.ipa</code>, Android release/debug <code>.apk</code>, and both a Windows NSIS installer (<code>Setup.exe</code>) and self-contained portable <code>.zip</code> (keeping state in <code>.\\Data\\</code> when <code>portable.txt</code> is present). An in-app updater checks <code>releases/latest</code> with <code>SHA256SUMS.txt</code> verification and <strong>Skip Version</strong> support on Windows, Android, and macOS.</p><h2 id="repository-downloads" tabindex="-1">Repository &amp; downloads <a class="header-anchor" href="#repository-downloads" aria-label="Permalink to &quot;Repository &amp; downloads&quot;">​</a></h2><ul><li><strong>Documentation &amp; plugin hub:</strong> <a href="https://musico.seanpnex.win" target="_blank" rel="noreferrer">musico.seanpnex.win</a> (User Guide, Official Plugins &amp; Extension API v1 Docs)</li><li><strong>Source code:</strong> <a href="https://github.com/SEANPNEX/Musico" target="_blank" rel="noreferrer">github.com/SEANPNEX/Musico</a> (MIT License)</li><li><strong>Releases:</strong> <a href="https://github.com/SEANPNEX/Musico/releases/latest" target="_blank" rel="noreferrer">Latest desktop &amp; mobile builds</a></li><li><strong>Extension developer docs:</strong> <a href="https://musico.seanpnex.win/developers/" target="_blank" rel="noreferrer">musico.seanpnex.win/developers/</a> · <a href="https://github.com/SEANPNEX/Musico/blob/main/docs/extensions/README.md" target="_blank" rel="noreferrer">GitHub README</a></li></ul>',15))])}const b=t(d,[["render",c]]);export{f as __pageData,b as default};
